//-- POWER

void sx1276_rfpower_calc(const int8_t power_dbm, int8_t* sx_power, int8_t* actual_power_dbm)
{
    if (power_dbm >= POWER_30_DBM) {
        *sx_power = 11;
        *actual_power_dbm = 30;
    } else if (power_dbm >= POWER_27_DBM) {
        *sx_power = 7;
        *actual_power_dbm = 27;
    } else if (power_dbm >= POWER_24_DBM) {
        *sx_power = 4;
        *actual_power_dbm = 24;
    } else {
        *sx_power = 0;
        *actual_power_dbm = 20;
    }
}

